284	     * whitespace; addresses are compared in their canonical normalized form (see
285	     * {@link AddressNormalizer}), so differences in letter case, runs of spaces or street-type
286	     * abbreviations are ignored. Returns an empty list when the owner has no last name or address to
287	     * match on.
288	     */
289	    private List<Owner> findHouseholdMembers(Owner owner) {
290	        String lastName = normalizeHouseholdKey(owner.getLastName());
291	        String address = AddressNormalizer.normalize(owner.getAddress());
292	        if (lastName == null || address == null) {
293	            return List.of();
294	        }
295	        return ownerRepository.findAll().stream()
296	            .filter(existing -> lastName.equals(normalizeHouseholdKey(existing.getLastName()))
297	                && address.equals(AddressNormalizer.normalize(existing.getAddress())))
298	            .toList();
