302	     * Resolve the stable {@code householdId} shared by a household. If any existing member already
303	     * carries one it is reused so the identifier stays stable as further owners join; otherwise a
304	     * new one is generated. The resolved value is back-filled onto every member that is missing it
305	     * (or has a different one) so all members of the household share the same identifier.
306	     */
307	    private String resolveHouseholdId(List<Owner> members) {
308	        String householdId = members.stream()
309	            .map(Owner::getHouseholdId)
310	            .filter(id -> id != null && !id.isBlank())
311	            .findFirst()
312	            .orElseGet(() -> UUID.randomUUID().toString());
313	        for (Owner member : members) {
314	            if (!householdId.equals(member.getHouseholdId())) {
